6	<title>Brick Breaker</title>
7	<style>
8	  html, body {
9	    margin: 0;
10	    padding: 0;
11	    height: 100%;
12	    background: radial-gradient(circle at 50% 30%, #1d2340 0%, #0b0e1a 70%);
13	    font-family: "Segoe UI", Helvetica, Arial, sans-serif;
