47	<body>
48	<h1>Brick Breaker</h1>
49	<canvas id="game" width="800" height="600"></canvas>
50	<div class="hint">Arrows / A-D or Mouse to move &middot; Space / Click to launch &middot; P to pause</div>
51	<script>
52	(function () {
53	  "use strict";
54	
55	  var canvas = document.getElementById("game");
56	  var ctx = canvas.getContext("2d");
57	  var W = canvas.width;
58	  var H = canvas.height;
59	
60	  // ---------- Constants ----------
61	  var HUD_H = 40;
62	  var PADDLE_W = 110;
63	  var PADDLE_H = 14;
64	  var PADDLE_Y = H - 40;
65	  var PADDLE_SPEED = 620; // px/s
66	  var BALL_R = 8;
67	  var MAX_BOUNCE_ANGLE = Math.PI / 3; // 60 degrees from vertical
68	  var START_LIVES = 3;
69	
70	  var BRICK_COLS = 10;
71	  var BRICK_GAP = 6;
72	  var BRICK_MARGIN_X = 30;
73	  var BRICK_TOP = HUD_H + 40;
74	  var BRICK_H = 22;
75	  var BRICK_W = (W - BRICK_MARGIN_X * 2 - BRICK_GAP * (BRICK_COLS - 1)) / BRICK_COLS;
76	
77	  // Level layouts: each char is a brick: '.' = empty, '1'..'3' = hits required.
78	  var LEVELS = [
79	    {
80	      name: "Level 1",
81	      ballSpeed: 380,
82	      layout: [
83	        "1111111111",
84	        "1111111111",
85	        "1111111111",
86	        "1111111111",
87	        "1111111111"
88	      ]
89	    },
90	    {
91	      name: "Level 2",
92	      ballSpeed: 470,
93	      layout: [
94	        "3333333333",
95	        "2.222222.2",
96	        "2212112122",
97	        "1111111111",
98	        "1.11..11.1",
99	        "1111111111",
100	        "2121212121"
101	      ]
102	    }
103	  ];
104	
105	  var ROW_COLORS = ["#ff5d73", "#ff9f43", "#feca57", "#1dd1a1", "#48dbfb", "#54a0ff", "#a29bfe"];
106	  var HIT_COLORS = { 2: "#c8d0e8", 3: "#8a93b8" }; // tint overlay for multi-hit
107	
108	  // ---------- State ----------
109	  var state = "start"; // start | ready | playing | paused | levelclear | gameover | win
110	  var pausedFrom = null;
111	  var score = 0;
112	  var lives = START_LIVES;
113	  var levelIndex = 0;
114	  var bricks = [];
115	  var levelClearTimer = 0;
116	
117	  var paddle = { x: W / 2 - PADDLE_W / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H };
118	  var ball = { x: 0, y: 0, vx: 0, vy: 0, r: BALL_R, speed: 0 };
119	
120	  var keys = { left: false, right: false };
121	
122	  // ---------- Setup ----------
123	  function buildLevel(idx) {
124	    var lvl = LEVELS[idx];
125	    bricks = [];
126	    for (var r = 0; r < lvl.layout.length; r++) {
127	      var row = lvl.layout[r];
128	      for (var c = 0; c < BRICK_COLS; c++) {
129	        var ch = row.charAt(c);
130	        if (ch === "." || ch === "") continue;
131	        var hits = parseInt(ch, 10);
132	        if (!(hits > 0)) continue;
133	        bricks.push({
134	          x: BRICK_MARGIN_X + c * (BRICK_W + BRICK_GAP),
135	          y: BRICK_TOP + r * (BRICK_H + BRICK_GAP),
136	          w: BRICK_W,
137	          h: BRICK_H,
138	          hits: hits,
139	          maxHits: hits,
140	          color: ROW_COLORS[r % ROW_COLORS.length],
141	          alive: true
142	        });
143	      }
144	    }
145	    ball.speed = lvl.ballSpeed;
146	  }
147	
148	  function resetBallOnPaddle() {
149	    ball.vx = 0;
150	    ball.vy = 0;
151	    ball.x = paddle.x + paddle.w / 2;
152	    ball.y = paddle.y - ball.r - 1;
153	  }
154	
155	  function newGame() {
156	    score = 0;
157	    lives = START_LIVES;
158	    levelIndex = 0;
159	    buildLevel(levelIndex);
160	    paddle.x = W / 2 - paddle.w / 2;
161	    resetBallOnPaddle();
162	    state = "ready";
163	  }
164	
165	  function launchBall() {
166	    // Launch slightly angled based on random small offset
167	    var angle = (Math.random() * 0.5 - 0.25) * MAX_BOUNCE_ANGLE;
168	    ball.vx = ball.speed * Math.sin(angle);
169	    ball.vy = -ball.speed * Math.cos(angle);
170	    state = "playing";
171	  }
172	
173	  function remainingBricks() {
174	    var n = 0;
175	    for (var i = 0; i < bricks.length; i++) if (bricks[i].alive) n++;
176	    return n;
177	  }
178	
179	  // ---------- Input ----------
180	  function primaryAction() {
181	    if (state === "start" || state === "gameover" || state === "win") {
182	      newGame();
183	    } else if (state === "ready") {
184	      launchBall();
185	    } else if (state === "paused") {
186	      togglePause();
187	    }
188	  }
189	
190	  function togglePause() {
191	    if (state === "playing" || state === "ready") {
192	      pausedFrom = state;
193	      state = "paused";
194	    } else if (state === "paused") {
195	      state = pausedFrom || "playing";
196	      pausedFrom = null;
197	    }
198	  }
199	
200	  window.addEventListener("keydown", function (e) {
201	    var k = e.key;
202	    var code = e.code;
203	    if (k === "ArrowLeft" || k === "ArrowRight" || k === "ArrowUp" || k === "ArrowDown" || k === " " || code === "Space") {
204	      e.preventDefault();
205	    }
206	    if (k === "ArrowLeft" || k === "a" || k === "A") keys.left = true;
207	    else if (k === "ArrowRight" || k === "d" || k === "D") keys.right = true;
208	    else if (k === " " || code === "Space") {
209	      if (!e.repeat) primaryAction();
210	    } else if (k === "p" || k === "P") {
211	      if (!e.repeat) togglePause();
212	    }
213	  });
214	
215	  window.addEventListener("keyup", function (e) {
216	    var k = e.key;
217	    if (k === "ArrowLeft" || k === "a" || k === "A") keys.left = false;
218	    else if (k === "ArrowRight" || k === "d" || k === "D") keys.right = false;
219	  });
220	
221	  window.addEventListener("blur", function () {
222	    keys.left = keys.right = false;
223	    if (state === "playing") togglePause();
224	  });
225	
226	  function canvasX(clientX) {
227	    var rect = canvas.getBoundingClientRect();
228	    return (clientX - rect.left) * (W / rect.width);
229	  }
230	
231	  canvas.addEventListener("mousemove", function (e) {
232	    if (state === "paused") return;
233	    setPaddleCenter(canvasX(e.clientX));
234	  });
235	
236	  canvas.addEventListener("mousedown", function (e) {
237	    e.preventDefault();
238	    if (e.button !== 0) return;
239	    if (state !== "paused") setPaddleCenter(canvasX(e.clientX));
240	    primaryAction();
241	  });
242	
243	  function setPaddleCenter(cx) {
244	    paddle.x = cx - paddle.w / 2;
245	    clampPaddle();
246	  }
247	
248	  function clampPaddle() {
249	    if (paddle.x < 0) paddle.x = 0;
250	    if (paddle.x + paddle.w > W) paddle.x = W - paddle.w;
251	  }
252	
253	  // ---------- Collision helpers ----------
254	  function clamp(v, lo, hi) { return v < lo ? lo : (v > hi ? hi : v); }
255	
256	  // Returns true if collided with a brick (and handled reflection)
257	  function collideBricks() {
258	    for (var i = 0; i < bricks.length; i++) {
259	      var b = bricks[i];
260	      if (!b.alive) continue;
261	      var cx = clamp(ball.x, b.x, b.x + b.w);
262	      var cy = clamp(ball.y, b.y, b.y + b.h);
263	      var dx = ball.x - cx;
264	      var dy = ball.y - cy;
265	      if (dx * dx + dy * dy > ball.r * ball.r) continue;
266	
267	      // Determine penetration depth on each axis to decide reflection side.
268	      var overlapLeft = (ball.x + ball.r) - b.x;
269	      var overlapRight = (b.x + b.w) - (ball.x - ball.r);
270	      var overlapTop = (ball.y + ball.r) - b.y;
271	      var overlapBottom = (b.y + b.h) - (ball.y - ball.r);
272	      var minX = Math.min(overlapLeft, overlapRight);
273	      var minY = Math.min(overlapTop, overlapBottom);
274	
275	      if (minX < minY) {
276	        // Side hit
277	        if (overlapLeft < overlapRight) {
278	          ball.x = b.x - ball.r;
279	          ball.vx = -Math.abs(ball.vx);
280	        } else {
281	          ball.x = b.x + b.w + ball.r;
282	          ball.vx = Math.abs(ball.vx);
283	        }
284	      } else {
285	        if (overlapTop < overlapBottom) {
286	          ball.y = b.y - ball.r;
287	          ball.vy = -Math.abs(ball.vy);
288	        } else {
289	          ball.y = b.y + b.h + ball.r;
290	          ball.vy = Math.abs(ball.vy);
291	        }
292	      }
293	
294	      b.hits--;
295	      if (b.hits <= 0) {
296	        b.alive = false;
297	        score += 10 * b.maxHits;
298	      } else {
299	        score += 2;
300	      }
301	      return true;
302	    }
303	    return false;
304	  }
305	
306	  function collidePaddle() {
307	    if (ball.vy <= 0) return false;
308	    var cx = clamp(ball.x, paddle.x, paddle.x + paddle.w);
309	    var cy = clamp(ball.y, paddle.y, paddle.y + paddle.h);
310	    var dx = ball.x - cx;
311	    var dy = ball.y - cy;
312	    if (dx * dx + dy * dy > ball.r * ball.r) return false;
313	    // Only bounce if ball center is above paddle bottom (avoid weird side-catches from below)
314	    if (ball.y > paddle.y + paddle.h) return false;
315	
316	    var rel = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
317	    rel = clamp(rel, -1, 1);
318	    var angle = rel * MAX_BOUNCE_ANGLE;
319	    ball.vx = ball.speed * Math.sin(angle);
320	    ball.vy = -ball.speed * Math.cos(angle);
321	    ball.y = paddle.y - ball.r - 0.01;
322	    return true;
323	  }
324	
325	  // ---------- Update ----------
326	  function update(dt) {
327	    // Paddle keyboard movement (allowed in ready & playing)
328	    if (state === "playing" || state === "ready") {
329	      var dir = (keys.right ? 1 : 0) - (keys.left ? 1 : 0);
330	      if (dir !== 0) {
331	        paddle.x += dir * PADDLE_SPEED * dt;
332	        clampPaddle();
333	      }
334	    }
335	
336	    if (state === "ready") {
337	      resetBallOnPaddle();
338	      return;
339	    }
340	
341	    if (state === "levelclear") {
342	      levelClearTimer -= dt;
343	      if (levelClearTimer <= 0) {
344	        levelIndex++;
345	        buildLevel(levelIndex);
346	        resetBallOnPaddle();
347	        state = "ready";
348	      }
349	      return;
350	    }
351	
352	    if (state !== "playing") return;
353	
354	    // Sub-step movement to prevent tunneling: max step = r/2
355	    var dist = ball.speed * dt;
356	    var steps = Math.max(1, Math.ceil(dist / (ball.r * 0.5)));
357	    var sdt = dt / steps;
358	
359	    for (var s = 0; s < steps; s++) {
360	      ball.x += ball.vx * sdt;
361	      ball.y += ball.vy * sdt;
362	
363	      // Walls
364	      if (ball.x - ball.r < 0) {
365	        ball.x = ball.r;
366	        ball.vx = Math.abs(ball.vx);
367	      } else if (ball.x + ball.r > W) {
368	        ball.x = W - ball.r;
369	        ball.vx = -Math.abs(ball.vx);
370	      }
371	      if (ball.y - ball.r < HUD_H) {
372	        ball.y = HUD_H + ball.r;
373	        ball.vy = Math.abs(ball.vy);
374	      }
375	
376	      collidePaddle();
377	
378	      if (collideBricks()) {
379	        if (remainingBricks() === 0) {
380	          if (levelIndex < LEVELS.length - 1) {
381	            state = "levelclear";
382	            levelClearTimer = 1.6;
383	          } else {
384	            state = "win";
385	          }
386	          return;
387	        }
388	      }
389	
390	      // Lost ball
391	      if (ball.y - ball.r > H) {
392	        lives--;
393	        if (lives <= 0) {
394	          lives = 0;
395	          state = "gameover";
396	        } else {
397	          resetBallOnPaddle();
398	          state = "ready";
399	        }
400	        return;
401	      }
402	    }
403	  }
404	
405	  // ---------- Render ----------
406	  function roundRect(x, y, w, h, r) {
407	    ctx.beginPath();
408	    ctx.moveTo(x + r, y);
409	    ctx.lineTo(x + w - r, y);
410	    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
411	    ctx.lineTo(x + w, y + h - r);
412	    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
413	    ctx.lineTo(x + r, y + h);
414	    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
415	    ctx.lineTo(x, y + r);
416	    ctx.quadraticCurveTo(x, y, x + r, y);
417	    ctx.closePath();
418	  }
419	
420	  function drawHUD() {
421	    ctx.fillStyle = "#171c38";
422	    ctx.fillRect(0, 0, W, HUD_H);
423	    ctx.fillStyle = "#2b3566";
